import {WORDS,ROUTES,EQUIPMENT,wordById,meaning} from './data.js';
import * as E from './engine.js';
import {platform} from './platform.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=platform.load();
const locales={};await Promise.all(['ko','en','ja','ru','es'].map(async lang=>{try{const r=await fetch(`locales/${lang}.json`);if(r.ok)locales[lang]=await r.json();}catch{}}));
const t=(key,args={})=>Object.entries(args).reduce((s,[k,v])=>s.replaceAll(`{${k}}`,String(v)),locales[state.settings.lang]?.[key]??locales.en?.[key]??key);
const text=(key,args)=>esc(t(key,args));
let phase='town',route=null,travelElapsed=0,wordIndex=-1,wordStage=-1,enemies=[],enemyIndex=0,battleQuestion=null,questionIndex=0,questionPool=[],answered=false,feedback=null,paused=false,autoElapsed=0,arrivalElapsed=0,animTime=0,attackTime=-10,hitTime=-10,attackInfo=null,reward=null,modalPanel=null,exam=null,review=null,bookMode='all',bookMask='none',toastTimer;
let audio=null;
const canvas=$('world'),ctx=canvas.getContext('2d'),images={};
const imageLoads=['woodland','hero','creatures','concept'].map(name=>new Promise(resolve=>{const img=new Image();images[name]=img;img.onload=resolve;img.onerror=()=>{toast(t('assetError'));resolve();};img.src=`assets/${name}.png`;}));
function save(){const ok=platform.save(state);$('saveLabel').textContent=t(ok?'savedLocal':'saveError');$('saveLabel').classList.toggle('storage-warning',!ok);}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function sound(kind){if(!state.settings.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;const notes=kind==='win'?[392,494,587,784]:kind==='wrong'?[180,120]:kind==='double'?[500,660]:[520];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(hz,now+i*.1);g.gain.setValueAtTime(.0001,now+i*.1);g.gain.exponentialRampToValueAtTime(.09,now+i*.1+.015);g.gain.exponentialRampToValueAtTime(.0001,now+i*.1+.22);o.connect(g);g.connect(audio.destination);o.start(now+i*.1);o.stop(now+i*.1+.24);});}catch{}}
function staticText(){document.documentElement.lang=state.settings.lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(key==='motto')el.innerHTML=t(key);else el.textContent=t(key);});for(const [id,key] of [['settingsButton','settings'],['soundButton','sound'],['closeModal','close'],['pauseButton',paused?'resume':'pause'],['world','sceneLabel']])$(id).setAttribute('aria-label',t(key));$('soundButton').textContent=state.settings.sound?'♫':'♪';$('soundButton').setAttribute('aria-pressed',String(state.settings.sound));}
function updateHUD(){const hpMax=E.maxHp(state),lv=E.level(state),cls=E.weapon(state).type;$('goldCount').textContent=state.gold;$('levelLabel').textContent=`Lv. ${lv}`;$('classLabel').textContent=t(cls);$('travelerClass').textContent=`${t(cls)} · Lv. ${lv}`;$('hpText').textContent=`${state.hp} / ${hpMax}`;$('hpFill').style.width=`${state.hp/hpMax*100}%`;$('hpFill').style.background=state.hp/hpMax>.5?'#9abb83':state.hp/hpMax>.25?'#ddbc63':'#d27665';$('shieldLabel').textContent=state.shield?'◇':'';$('shieldLabel').title=t('shield');$('xpText').textContent=`${state.xp%100} / 100`;$('xpFill').style.width=`${state.xp%100}%`;$('seenCount').textContent=state.seen.length;$('correctCount').textContent=Object.values(state.records).filter(r=>r.correct>0).length;$('medalCount').textContent=state.medals.length;document.querySelectorAll('.route-node').forEach(el=>{const town=Number(el.dataset.town);el.classList.toggle('visited',town<=state.unlocked);el.classList.toggle('current',phase==='town'&&town===state.town);el.setAttribute('aria-current',phase==='town'&&town===state.town?'location':'false');});$('autoButton').textContent=`${t('auto')} ${t(state.settings.auto?'on':'off')}`;$('autoButton').classList.toggle('active',state.settings.auto);$('autoButton').setAttribute('aria-pressed',String(state.settings.auto));$('bagButton').textContent=t('bag');$('pauseButton').textContent=paused?'▶':'Ⅱ';$('pauseButton').setAttribute('aria-label',t(paused?'resume':'pause'));updateEnemy();}
function updateEnemy(){const el=$('enemyLabel');el.hidden=phase!=='battle';if(phase==='battle'){const e=enemies[enemyIndex];el.innerHTML=`${text(e.name)} <small>${Math.max(0,e.hp)} / ${e.maxHp}</small><div class="hp-track"><span style="width:${Math.max(0,e.hp)/e.maxHp*100}%"></span></div>`;}}
function setSceneUI(){const moving=phase==='travel'||phase==='arriving';$('sceneCaption').hidden=phase==='travel'||phase==='battle';$('wordCard').hidden=!(phase==='travel'||phase==='battle');$('travelProgress').hidden=!moving;$('pauseButton').hidden=!['travel','battle'].includes(phase);$('autoButton').hidden=!['travel','battle'].includes(phase);$('bagButton').hidden=phase!=='battle';$('locationName').textContent=t(phase==='town'?`town${state.town}`:route?.name||`town${state.town}`);$('locationEyebrow').textContent=phase==='town'?`CHAPTER 01 · ${String(state.town+1).padStart(2,'0')}`:t('route');$('scene').dataset.phase=phase;updateHUD();}
function renderTown(){phase='town';paused=false;setSceneUI();const first=state.seen.length===0;$('sceneCaption').innerHTML=`<span class="ornament">✦</span><p>${text(first?'welcome':'townRest')}</p><span class="ornament">✦</span>`;$('interaction').className='interaction';$('interaction').innerHTML=`<div class="town-main"><span class="eyebrow">${text(state.town===2?'complete':'townRest')}</span><h2>${text(first?'readyTitle':state.town===2?'completeDesc':'healed')}</h2>${first?`<p>${text('readyDesc')}</p>`:''}<div class="town-actions"><button class="secondary" data-panel="shop">${text('shop')}</button><button class="secondary" data-panel="equipment">${text('equipment')}</button><button class="secondary" data-panel="academy">${text('academy')}</button>${state.town>0?`<button class="secondary" data-depart="${state.town-1}">${text('revisit')}</button>`:''}</div></div>${state.town<2?`<button class="primary" data-depart="${state.town+1}">${text(first?'depart':'nextTown')}</button>`:''}`;save();}
function depart(target){if(phase!=='town')return false;const r=E.beginJourney(state,target);if(!r){toast(t('mapLocked'));return false;}route=r;phase='travel';travelElapsed=0;wordIndex=-1;wordStage=-1;questionIndex=0;paused=false;closeModal(true);setSceneUI();$('interaction').className='interaction traveling';$('interaction').innerHTML=`<div><span class="eyebrow">${text('learnedLabel',{count:5})}</span><h2>${text('travelTitle')}</h2><p>${text('travelDesc')}</p></div>`;showTravelWord();save();return true;}
function showTravelWord(){const index=Math.min(4,Math.floor(travelElapsed/8)),stage=Math.min(2,Math.floor((travelElapsed%8)/2.67));if(index!==wordIndex){wordIndex=index;E.markSeen(state,route.words[index]);save();updateHUD();}if(stage!==wordStage||$('wordCard').dataset.index!==String(index)){wordStage=stage;$('wordCard').dataset.index=String(index);const w=wordById(route.words[index]);$('wordCard').innerHTML=`<div class="word-counter">${text(['wordStage','meaningStage','togetherStage'][stage])} · ${index+1} / 5</div><div class="word ${stage===1?'masked':''}" lang="en">${esc(w.word)}</div><div class="meaning ${stage===0?'masked':''}">${esc(meaning(w,state.settings.meaningLang))}</div>`;}$('travelText').textContent=t('progress',{current:index+1,total:5});$('travelFill').style.width=`${Math.min(100,travelElapsed/40*100)}%`;}
function beginBattle(){phase='battle';state.stats.battles++;enemies=E.createEnemies();enemyIndex=0;questionIndex=0;questionPool=E.shuffled(route.words);feedback=null;setSceneUI();nextQuestion();save();sound('win');}
function nextQuestion(){if(state.hp<=0){phase='defeat';setSceneUI();renderOutcome(false);return;}if(enemies[enemyIndex].hp<=0){enemyIndex++;if(enemyIndex>=enemies.length){phase='victory';reward=E.win(state);setSceneUI();renderOutcome(true);save();sound('win');return;}}
 const id=questionPool[questionIndex%questionPool.length];battleQuestion=E.question(state,id,questionIndex%3===2?'spell':'choice');questionIndex++;answered=false;feedback=null;autoElapsed=0;renderBattle();}
function questionHTML(q,examMode=false){const w=wordById(q.id);return `<div class="question-head"><h2>${text(q.type==='choice'?'choicePrompt':'spellPrompt')}</h2><small>${examMode?'':text('enemyCount',{count:enemies.length-enemyIndex})}</small></div>${q.type==='choice'?`<div class="answers">${q.choices.map((id,i)=>`<button class="answer" data-answer="${id}"><span>${i+1}</span>${esc(meaning(wordById(id),state.settings.meaningLang))}</button>`).join('')}</div>`:`<form class="spelling-form" id="${examMode?'examForm':'battleForm'}"><input name="answer" type="text" autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="${text('spellPlaceholder')}" placeholder="${text('spellPlaceholder')}" required maxlength="60"><button class="primary" type="submit">${text('submit')}</button></form>`}`;}
function renderBattle(){setSceneUI();const q=battleQuestion,w=wordById(q.id);$('wordCard').innerHTML=`<div class="word-counter">${text(q.type==='choice'?'wordStage':'meaningStage')}</div><div class="${q.type==='choice'?'word':'meaning'}" ${q.type==='choice'?'lang="en"':''}>${esc(q.type==='choice'?w.word:meaning(w,state.settings.meaningLang))}</div><div class="meaning">${answered?esc(q.type==='choice'?meaning(w,state.settings.meaningLang):w.word):'✧'}</div>`;$('interaction').className='interaction battle';$('interaction').innerHTML=questionHTML(q)+`<div class="feedback" role="status">${feedback?`${text(feedback.correct?'correct':'wrong')} · ${text('answerWas',{word:w.word,meaning:meaning(w,state.settings.meaningLang)})}${feedback.auto?` · ${text('autoAnswer')}`:''}`:text('battleHint')}</div>${answered?`<button class="secondary next-answer" data-action="next">${text('continue')}</button>`:''}`;
 if(answered){$('interaction').querySelectorAll('.answer,input,form button').forEach(el=>el.disabled=true);$('interaction').querySelectorAll('.answer').forEach(el=>{if(el.dataset.answer===q.id)el.classList.add('correct');else if(el.dataset.answer===feedback.selection)el.classList.add('wrong');});}else if(q.type==='spell'&&!state.settings.auto&&!modal.open&&!paused&&window.innerWidth>800){$('battleForm').elements.answer.focus({preventScroll:true});}}
function answer(value,auto=false){if(phase!=='battle'||answered||paused||modal.open)return false;const q=battleQuestion,correct=auto?Math.random()<E.chances(state).auto:q.type==='choice'?value===q.id:E.isCorrect(q.id,value);answered=true;feedback={correct,selection:value,auto};E.recordAnswer(state,q.id,correct,q.type,auto);if(correct){attackInfo=E.attack(state);enemies[enemyIndex].hp=Math.max(0,enemies[enemyIndex].hp-attackInfo.total);attackTime=animTime;floatText(`${attackInfo.critical?t('critical')+' ':''}${attackInfo.double?`${attackInfo.hit} + ${attackInfo.hit}`:attackInfo.hit}`);sound(attackInfo.double?'double':'correct');}else{const impact=E.receiveAttack(state);hitTime=animTime;floatText(impact.kind==='damage'?`−${impact.damage}`:t(impact.kind));sound('wrong');}save();renderBattle();autoElapsed=0;return true;}
function floatText(value){const el=$('floatText');el.textContent=value;el.classList.remove('animate');void el.offsetWidth;el.classList.add('animate');}
function renderOutcome(victory){$('wordCard').hidden=!victory;if(victory&&battleQuestion){const lastWord=wordById(battleQuestion.id);$('wordCard').innerHTML=`<div class="word-counter">✦ ${text('correct')} ✦</div><div class="word">${esc(lastWord.word)}</div><div class="meaning">${esc(meaning(lastWord,state.settings.meaningLang))}</div>`;}$('sceneCaption').hidden=victory;$('sceneCaption').innerHTML=`<span class="ornament">✦</span><p>${text(victory?'victory':'defeat')}</p><span class="ornament">✦</span>`;$('interaction').className='interaction';$('interaction').innerHTML=`<div class="results"><span class="eyebrow">${victory?'VICTORY':'A MOMENT TO REST'}</span><h2>${text(victory?'victory':'defeat')}</h2>${victory?`<div class="rewards"><span>◈ ${text('rewardGold',{amount:reward.gold})}</span><span>✧ ${text('rewardXp',{amount:reward.xp})}</span></div>`:''}<p>${text(victory?'victoryDesc':'defeatDesc')}</p><button class="primary" data-action="${victory?'arrive':'return'}">${text(victory?'goTown':'returnTown')}</button></div>`;}
function startArrival(){if(phase!=='victory')return;phase='arriving';arrivalElapsed=0;setSceneUI();$('sceneCaption').innerHTML=`<p>${text('arriving')}</p>`;$('interaction').className='interaction traveling';$('interaction').innerHTML=`<h2>${text('arriving')}</h2>`;}
function finishArrival(){E.arrive(state);renderTown();toast(t('healed'));}
function returnTown(){if(phase!=='defeat')return;E.die(state);renderTown();}
const modal=$('modal');
function openPanel(panel){if(['shop','equipment','academy'].includes(panel)&&phase!=='town'){toast(t('notInTown'));return;}modalPanel=panel;renderPanel();if(!modal.open)modal.showModal();}
function closeModal(force=false){if(!force&&exam&&!exam.finished){if(!confirm(t('examLeave')))return;}modal.close();modalPanel=null;exam=null;review=null;}
function renderPanel(){const key={shop:'shop',equipment:'equipment',academy:'academy',book:'wordbook',status:'status',map:'map',settings:'settings',bag:'bag',help:'howTo',review:'reviewWords'}[modalPanel]||'academy';$('modalTitle').textContent=t(key);const c=$('modalContent');if(modalPanel==='book')renderBook();else if(modalPanel==='status')renderStatus();else if(modalPanel==='settings')renderSettings();else if(modalPanel==='map')renderMap();else if(modalPanel==='shop'||modalPanel==='equipment')renderShop();else if(modalPanel==='bag')renderBag();else if(modalPanel==='academy')renderAcademy();else if(modalPanel==='exam')renderExam();else if(modalPanel==='review')renderReview();else if(modalPanel==='help')c.innerHTML=`<ol class="help-steps">${[1,2,3,4,5].map(i=>`<li>${text('help'+i)}</li>`).join('')}</ol><p class="muted">${text('localNote')}</p><p class="muted">${text('noAds')}</p>`;drawMerchant();}
function renderBook(){const ids=state.seen.filter(id=>bookMode!=='mistakes'||state.records[id]?.wrong>0);$('modalContent').innerHTML=`<div class="book-controls"><button class="secondary" data-book="all">${text('allWords')}</button><button class="secondary" data-book="mistakes">${text('reviewWords')}</button><button class="secondary" data-mask="meaning">${text('hideMeaning')}</button><button class="secondary" data-mask="word">${text('hideWord')}</button><button class="secondary" data-mask="none">${text('showAll')}</button></div>${ids.length?`<div class="book-list">${ids.map(id=>{const w=wordById(id),r=state.records[id];return `<div class="book-row"><div><strong class="${bookMask==='word'?'masked-value':''}">${esc(w.word)}</strong><small>${text('record',r)}</small>${r.auto?`<small>${text('autoRecord',{count:r.auto})}</small>`:''}</div><button class="meaning ${bookMask==='meaning'?'masked-value':''}" data-reveal-row aria-label="${text('reveal')}">${esc(meaning(w,state.settings.meaningLang))}</button></div>`;}).join('')}</div>`:`<p class="empty">${text(bookMode==='mistakes'?'reviewEmpty':'bookEmpty')}</p>`}${state.seen.length?`<p class="muted">${text('reviewReward')}</p><button class="primary" data-action="review">${text('reviewStart')}</button>`:''}`;}
function renderStatus(){const s=E.stats(state),ch=E.chances(state);$('modalContent').innerHTML=`<div class="stat-grid">${Object.entries(s).map(([k,v])=>`<div class="stat-card"><b>${v}</b><span>${text(k)}</span><p>${text(k+'Desc')}</p></div>`).join('')}</div><p class="muted">${text('double')} ${Math.round(ch.double*100)}% · ${text('critical')} ${Math.round(ch.critical*100)}% · ${text('auto')} ${Math.round(ch.auto*100)}%</p><p class="muted">${text('capacity')}: ${E.weapon(state).weight} / ${E.capacity(state)}</p>${state.owned.map(id=>{const w=EQUIPMENT.find(e=>e.id===id);return `<div class="equipment-row"><div><h3>${text(w.name)}</h3><p>${text(w.type)} · ${text('weight')} ${w.weight} · ${text('attackPower',{amount:w.power})}</p></div><button class="secondary" data-equip="${id}" ${state.weapon===id||phase!=='town'?'disabled':''}>${text(state.weapon===id?'equipped':'equip')}</button></div>`;}).join('')}${phase!=='town'?`<p class="muted">${text('notInTown')}</p>`:''}`;}
function merchantCanvas(index){return `<canvas class="merchant" width="150" height="130" data-merchant="${index}" aria-label="${text(index===4?'merchantOwl':index===5?'merchantDog':'merchantCat')}"></canvas>`;}
function drawMerchant(){document.querySelectorAll('[data-merchant]').forEach(c=>{const cc=c.getContext('2d');cc.clearRect(0,0,c.width,c.height);sprite(cc,Number(c.dataset.merchant),c.width/2,c.height-5,125);});}
function renderShop(){const equip=modalPanel==='equipment';$('modalContent').innerHTML=merchantCanvas(equip?5:6)+`<p class="muted">◈ ${state.gold} ${text('gold')}</p>`+(equip?EQUIPMENT.filter(e=>(e.town||0)<=state.town).map(e=>`<div class="shop-row"><div><h3>${text(e.name)}</h3><p>${text(e.type)} · ${text('weight')} ${e.weight} · ${text('attackPower',{amount:e.power})}</p></div><button class="secondary" data-buy="${e.id}" ${state.owned.includes(e.id)||state.gold<e.cost||e.weight>E.capacity(state)?'disabled':''}>${state.owned.includes(e.id)?text('owned'):`${e.cost} ◈`}</button></div>`).join(''):['potion','guard'].map(id=>`<div class="shop-row"><div><h3>${text(id)}</h3><p>${text(id+'Desc')} · ${text('itemCount',{count:state[id==='potion'?'potions':'guards']})}</p></div><button class="secondary" data-buy="${id}" ${state.gold<(id==='potion'?20:25)?'disabled':''}>${text('buy')} · ${id==='potion'?20:25} ◈</button></div>`).join(''));}
function renderBag(){$('modalContent').innerHTML=['potion','guard'].map(id=>`<div class="shop-row"><div><h3>${text(id)} × ${state[id==='potion'?'potions':'guards']}</h3><p>${text(id+'Desc')}</p></div><button class="secondary" data-use="${id}" ${state[id==='potion'?'potions':'guards']<=0||(id==='potion'?state.hp>=E.maxHp(state):state.shield>0)?'disabled':''}>${text('use')}</button></div>`).join('')+`<p class="muted">${state.hp} / ${E.maxHp(state)} HP ${state.shield?'◇ '+text('shield'):''}</p>`;}
function renderMap(){$('modalContent').innerHTML=`<p class="modal-intro">${text('mapDescLong')}</p><div class="map-grid">${Array.from({length:20},(_,i)=>`<button class="map-tile ${i===state.town?'current':''} ${i>state.unlocked?'locked':''}" data-map-town="${i}" ${i===state.town||phase!=='town'?'disabled':''}><span>${i<=state.unlocked?'✧':'?'}</span><span>${i<=state.unlocked?text('town'+i):String(i+1).padStart(2,'0')}</span></button>`).join('')}</div><p class="muted">${text('mapTravel')}</p>`;}
const languageOptions=[['ko','한국어'],['en','English'],['ja','日本語'],['ru','Русский'],['es','Español']];
function langSelect(id,value){return `<select id="${id}">${languageOptions.map(([k,n])=>`<option value="${k}" ${value===k?'selected':''}>${n}</option>`).join('')}<option disabled>中文 · ${text('comingSoon')}</option></select>`;}
function renderSettings(){$('modalContent').innerHTML=`<p class="muted">${text('settingsNote')}</p><label class="setting-row">${text('uiLanguage')}${langSelect('uiLang',state.settings.lang)}</label><label class="setting-row">${text('meaningLanguage')}${langSelect('meaningLang',state.settings.meaningLang)}</label><p class="muted">${text('learnLanguage')}</p><label class="setting-row">${text('speed')}<select id="speedSelect">${[[.65,'speedSlow'],[1,'speedNormal'],[1.6,'speedFast'],[2.5,'speedTest']].map(([n,k])=>`<option value="${n}" ${n===state.settings.speed?'selected':''}>${text(k)}</option>`).join('')}</select></label><label class="setting-row">${text('sound')}<input type="checkbox" id="soundCheck" ${state.settings.sound?'checked':''}></label><label class="setting-row">${text('reduceMotion')}<input type="checkbox" id="motionCheck" ${state.settings.reducedMotion?'checked':''}></label><p class="muted">${text('localNote')}</p><button class="secondary danger" data-action="reset">${text('reset')}</button>`;}
function renderAcademy(){$('modalContent').innerHTML=merchantCanvas(4)+`<p class="modal-intro">${text(state.town===0?'academyIntro':state.town===1?'academyAway':'academyDesc')}</p>${state.town===2?`${state.medals.includes(2)?`<p class="muted">✧ ${text('examMedalOwned')}</p>`:''}<button class="primary" data-action="exam" ${state.seen.length<10?'disabled':''}>${text('startExam')}</button>${state.seen.length<10?`<p class="muted">${text('examNeed')}</p>`:''}`:''}`;}
function startExam(){if(state.town!==2||state.seen.length<10||phase!=='town')return;exam={questions:E.createExam(state),index:0,score:0,answered:false,finished:false,results:[]};modalPanel='exam';renderPanel();}
function renderExam(){if(!exam)return;if(exam.finished){$('modalContent').innerHTML=`<div class="results"><span style="font-size:56px;color:#b5964e">${E.passedExam(exam.score,exam.questions.length)?'✧':'✦'}</span><h2>${text(E.passedExam(exam.score,exam.questions.length)?'examPassed':'examFailed')}</h2><p>${text('examResult',{score:exam.score,total:exam.questions.length})}</p><button class="primary" data-action="retryExam">${text('tryAgain')}</button></div>`;return;}const q=exam.questions[exam.index],w=wordById(q.id);$('modalContent').innerHTML=`<div class="exam-progress"><i style="width:${exam.index/exam.questions.length*100}%"></i></div><div class="exam-paper"><span class="eyebrow">${text(q.type==='choice'?'examChoice':'examSpell')}</span><p class="muted">${text('examProgress',{current:exam.index+1,total:exam.questions.length})}</p><h3>${esc(q.type==='choice'?w.word:meaning(w,state.settings.meaningLang))}</h3>${questionHTML(q,true)}<div class="feedback" role="status">${exam.answered?`${text(exam.lastCorrect?'correct':'wrong')} · ${esc(w.word)} · ${esc(meaning(w,state.settings.meaningLang))}`:''}</div>${exam.answered?`<button class="secondary" data-action="examNext">${text('continue')}</button>`:''}</div>`;if(exam.answered)$('modalContent').querySelectorAll('.answer,input,form button').forEach(el=>el.disabled=true);else if(q.type==='spell'&&window.innerWidth>800)$('examForm').elements.answer.focus();}
function answerExam(value){if(!exam||exam.finished||exam.answered)return;const q=exam.questions[exam.index];const correct=q.type==='choice'?value===q.id:E.isCorrect(q.id,value);exam.answered=true;exam.lastCorrect=correct;if(correct)exam.score++;exam.results.push({id:q.id,correct,type:q.type});sound(correct?'correct':'wrong');renderExam();}
function nextExam(){if(!exam||!exam.answered)return;exam.index++;if(exam.index>=exam.questions.length){exam.finished=true;exam.results.forEach(r=>E.recordAnswer(state,r.id,r.correct,r.type,false));if(E.passedExam(exam.score,exam.questions.length)&&!state.medals.includes(2)){state.medals.push(2);state.gold+=50;state.xp+=50;}save();updateHUD();sound('win');}else exam.answered=false;renderExam();}
function startReview(){const missed=state.seen.filter(id=>state.records[id]?.wrong>0);review={ids:(missed.length?missed:state.seen).slice(0,5),index:0,revealed:false};if(!review.ids.length)return;modalPanel='review';renderPanel();}
function renderReview(){const w=wordById(review.ids[review.index]);$('modalContent').innerHTML=`<div class="results"><span class="eyebrow">${review.index+1} / ${review.ids.length}</span><p>${text('reviewQuestion')}</p><h2>${esc(meaning(w,state.settings.meaningLang))}</h2>${review.revealed?`<p style="font:600 40px 'Cormorant Garamond',serif">${esc(w.word)}</p><button class="primary" data-action="reviewNext">${text(review.index===review.ids.length-1?'completeReview':'reviewNext')}</button>`:`<button class="primary" data-action="revealReview">${text('reveal')}</button>`}</div>`;}
function refreshLanguage(){staticText();updateHUD();if(phase==='town')renderTown();else if(phase==='battle')renderBattle();else if(phase==='travel'){wordStage=-1;showTravelWord();$('interaction').innerHTML=`<div><h2>${text(paused?'paused':'travelTitle')}</h2><p>${text('travelDesc')}</p></div>`;}else if(phase==='victory'||phase==='defeat')renderOutcome(phase==='victory');if(modal.open)renderPanel();}
function togglePause(){if(!['travel','battle'].includes(phase))return;paused=!paused;updateHUD();if(phase==='travel')$('interaction').querySelector('h2').textContent=t(paused?'paused':'travelTitle');}
$('settingsButton').onclick=()=>openPanel('settings');$('helpButton').onclick=()=>openPanel('help');$('closeModal').onclick=()=>closeModal();modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('soundButton').onclick=()=>{state.settings.sound=!state.settings.sound;staticText();save();toast(t(state.settings.sound?'soundOn':'soundOff'));sound('correct');};$('pauseButton').onclick=togglePause;$('bagButton').onclick=()=>openPanel('bag');$('autoButton').onclick=()=>{if(state.unlocked<1){toast(t('autoLocked'));return;}state.settings.auto=!state.settings.auto;autoElapsed=0;updateHUD();save();if(state.settings.auto)toast(t('autoHelp'));};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;if(el.dataset.panel)openPanel(el.dataset.panel);if(el.dataset.depart!==undefined)depart(Number(el.dataset.depart));if(el.dataset.town!==undefined){if(phase==='town'&&Number(el.dataset.town)!==state.town)depart(Number(el.dataset.town));}if(el.dataset.mapTown!==undefined){const n=Number(el.dataset.mapTown);if(n<3&&Math.abs(n-state.town)===1)depart(n);else toast(t('mapLocked'));}if(el.dataset.answer){if(modalPanel==='exam')answerExam(el.dataset.answer);else answer(el.dataset.answer);}if(el.dataset.buy){toast(t(E.buy(state,el.dataset.buy)?'purchaseDone':'cannotBuy'));save();updateHUD();renderPanel();}if(el.dataset.equip&&phase==='town'){if(state.owned.includes(el.dataset.equip)&&EQUIPMENT.find(w=>w.id===el.dataset.equip).weight<=E.capacity(state)){state.weapon=el.dataset.equip;save();updateHUD();renderPanel();}}if(el.dataset.use){const ok=E.useItem(state,el.dataset.use);if(!ok)toast(t('cannotUse'));save();updateHUD();renderPanel();}if(el.dataset.book){bookMode=el.dataset.book;renderBook();}if(el.dataset.mask){bookMask=el.dataset.mask;renderBook();}if(el.hasAttribute('data-reveal-row'))el.closest('.book-row').querySelectorAll('.masked-value').forEach(n=>n.classList.remove('masked-value'));
 switch(el.dataset.action){case'next':if(answered&&!paused)nextQuestion();break;case'arrive':startArrival();break;case'return':returnTown();break;case'exam':case'retryExam':startExam();break;case'examNext':nextExam();break;case'review':startReview();break;case'revealReview':review.revealed=true;renderReview();break;case'reviewNext':if(review.index+1>=review.ids.length){state.shield=1;save();updateHUD();closeModal(true);toast(t('reviewDone'));}else{review.index++;review.revealed=false;renderReview();}break;case'reset':if(confirm(t('resetConfirm'))){state=E.freshState();closeModal(true);staticText();renderTown();}break;}
});
document.addEventListener('submit',e=>{if(e.target.id==='battleForm'||e.target.id==='examForm'){e.preventDefault();const value=new FormData(e.target).get('answer');if(!String(value).trim())return;if(e.target.id==='examForm')answerExam(value);else answer(value);}});
document.addEventListener('change',e=>{if(e.target.id==='uiLang'){state.settings.lang=e.target.value;refreshLanguage();}if(e.target.id==='meaningLang'){state.settings.meaningLang=e.target.value;refreshLanguage();}if(e.target.id==='speedSelect')state.settings.speed=Number(e.target.value);if(e.target.id==='soundCheck'){state.settings.sound=e.target.checked;staticText();sound('correct');}if(e.target.id==='motionCheck')state.settings.reducedMotion=e.target.checked;save();});
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.repeat)return;const n=Number(e.key);if(n>=1&&n<=4){const parent=modalPanel==='exam'?$('modalContent'):!modal.open?$('interaction'):null;const btn=parent?.querySelectorAll('.answer')[n-1];if(btn&&!btn.disabled){e.preventDefault();btn.click();}}if(e.code==='Space'&&!modal.open){e.preventDefault();togglePause();}});
window.addEventListener('pagehide',save);
let w=0,h=0,dpr=1;
function resize(){w=canvas.clientWidth;h=canvas.clientHeight;dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
new ResizeObserver(resize).observe(canvas);
function sprite(context,index,x,bottom,height){const img=images.creatures;if(!img?.naturalWidth)return;const cw=384,ch=512;const width=height*cw/ch;context.drawImage(img,(index%4)*cw,Math.floor(index/4)*ch,cw,ch,x-width/2,bottom-height,width,height);}
function heroDraw(x,bottom,size,moving){const img=images.hero;if(!img?.naturalWidth)return;const mage=E.weapon(state).type==='mage';let crop=mage?[1725,45,415,596]:[22,129,514,506];const attacking=animTime-attackTime<.5;if(!mage&&attacking)crop=[1030,130,690,506];else if(!mage&&moving&&Math.floor(animTime*7)%2)crop=[562,130,453,506];let height=size,width=size*crop[2]/crop[3];let bob=moving?Math.sin(animTime*14)*3:Math.sin(animTime*2)*1.5;let jump=0;if(moving&&!state.settings.reducedMotion){const cycle=animTime%13;if(cycle>8&&cycle<9)jump=Math.sin((cycle-8)*Math.PI)*28;if(cycle>11&&cycle<11.8)height*=.83;}if(state.settings.reducedMotion)bob=0;ctx.save();if(animTime-hitTime<.4)ctx.globalAlpha=.45+Math.abs(Math.sin(animTime*35))*.5;ctx.drawImage(img,...crop,x-width/2+(attacking?Math.sin((animTime-attackTime)*6)*20:0),bottom-height-bob-jump,width,height);ctx.restore();if(state.shield){ctx.strokeStyle='#ffffe9cc';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,bottom-size*.48,size*.5,size*.6,0,0,Math.PI*2);ctx.stroke();}}
function drawWorld(){ctx.clearRect(0,0,w,h);const moving=['travel','arriving'].includes(phase)&&!paused&&!modal.open;const bg=images.woodland;if(bg?.naturalWidth){const scale=Math.max(w/1536,h/820);const bw=1536*scale,bh=1024*scale;let offset=0;if(moving&&!state.settings.reducedMotion)offset=(animTime*24)%(bw*2);if(phase==='town'&&images.concept?.naturalWidth){const cx=[33,287,530][state.town],cy=682,cw=242,ch=230;const ratio=Math.max(w/cw,h/ch);const dw=cw*ratio,dh=ch*ratio;ctx.drawImage(images.concept,cx,cy,cw,ch,(w-dw)/2,(h-dh)/2,dw,dh);ctx.fillStyle='#f3eddb22';ctx.fillRect(0,0,w,h);}else{for(let k=-1;k<3;k++){let xx=k*bw-offset;ctx.save();if(k%2!==0){ctx.translate(xx+bw,0);ctx.scale(-1,1);xx=0;}ctx.drawImage(bg,xx,h-bh+35,bw,bh);ctx.restore();}if(route?.id===1){ctx.fillStyle='#273e7625';ctx.fillRect(0,0,w,h);}}}else{ctx.fillStyle='#b5c4aa';ctx.fillRect(0,0,w,h);}const floor=h-90,heroX=phase==='town'?w*.37:w*.27;heroDraw(heroX,floor,Math.min(160,w*.32),moving);if(phase==='town'){sprite(ctx,6,w*.72,floor+2,112);}if(phase==='battle'){const en=enemies[enemyIndex];if(en){const size=en.sprite===0?115:en.sprite===1?148:178;const bounce=state.settings.reducedMotion?0:Math.sin(animTime*3)*3;ctx.save();if(en.hp<=0)ctx.globalAlpha=.25;sprite(ctx,en.sprite,w*.73,floor+8+bounce,size);ctx.restore();if(animTime-attackTime<.55&&!state.settings.reducedMotion){ctx.strokeStyle='#fff9cf';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(w*.65,floor-size*.8);ctx.lineTo(w*.78,floor-size*.2);ctx.stroke();}}}if(['victory','arriving'].includes(phase))sprite(ctx,7,w*.7,floor+3,112);
 if(!state.settings.reducedMotion&&phase!=='town'){ctx.fillStyle='#fff2bd';for(let i=0;i<9;i++){const x=(i*127+animTime*(5+i%3))%(w+20),y=h*.4+Math.sin(animTime*.6+i)*h*.17;ctx.globalAlpha=.15+Math.abs(Math.sin(animTime+i))*.3;ctx.beginPath();ctx.arc(x,y,1.5,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}}
let last=performance.now();function frame(now){const dt=Math.min(.08,(now-last)/1000);last=now;const active=!document.hidden&&!modal.open&&!paused;if(active){animTime+=dt;if(phase==='travel'){travelElapsed+=dt*state.settings.speed;if(travelElapsed>=40)beginBattle();else showTravelWord();}else if(phase==='battle'&&state.settings.auto&&state.unlocked>=1){autoElapsed+=dt;if(!answered&&autoElapsed>2.2)answer('',true);else if(answered&&autoElapsed>1.7){autoElapsed=0;nextQuestion();}}else if(phase==='arriving'){arrivalElapsed+=dt;$('travelText').textContent=t('arriving');$('travelFill').style.width=`${Math.min(100,arrivalElapsed/3*100)}%`;if(arrivalElapsed>=3)finishArrival();}}drawWorld();requestAnimationFrame(frame);}
staticText();renderTown();resize();requestAnimationFrame(frame);
Promise.all(imageLoads).then(()=>{const p=$('portrait');p.style.backgroundImage='url(assets/hero.png)';p.style.backgroundSize='236px auto';p.style.backgroundPosition='-195px -5px';drawMerchant();});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_word_runner_progress',description:'Read the current village, phase, HP, wordbook and learning records. No game state changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(input&&Object.keys(input).length)throw new Error('No arguments supported');return {phase,town:state.town,hp:state.hp,gold:state.gold,seen:state.seen,records:state.records,medals:state.medals};}});register({name:'start_word_runner_journey',description:'Start travel to an adjacent village, exactly like the journey button. Only available while resting in a village.',inputSchema:{type:'object',properties:{target:{type:'integer',minimum:0,maximum:2}},required:['target'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='target')||!Number.isInteger(input.target)||input.target<0||input.target>2||!depart(input.target))throw new Error('Journey unavailable');return {phase,from:state.journey.from,to:state.journey.to};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
